      "formMessage": "Why do you want to join the Agri Traders Program?",
      "btnSubmitApply": "Submit Application",
      "btnSubmitInquiry": "Request Brochure",
      "heroSub": "Building the next generation of professional Vietnamese agricultural trade representatives for global markets."
