      "pfItem7": "Hệ thống quản lý tiến trình phát triển khách hàng trên CRM",
      "pfItem8": "Kế hoạch hành động 30 ngày thực chiến có cố vấn đồng hành",
      "fromTrainingEyebrow": "TỪ ĐÀO TẠO ĐẾN KINH DOANH XUẤT KHẨU THỰC TẾ",
      "realBusinessTitle": "Tốt Nghiệp Sẵn Sàng Xuất Khẩu. Đồng Hành Cùng VAC.",
      "realBusinessPara1": "Hoàn thành Chương trình Đào tạo Thương nhân Nông nghiệp Việt Nam không phải là điểm kết thúc của hành trình học tập—mà là khởi đầu của cơ hội kinh doanh xuất khẩu thực chiến.",
      "realBusinessPara2": "Học viên tốt nghiệp sẽ sở hữu kiến thức cốt lõi, công cụ thực hành và khung thương mại cần thiết để bắt đầu phát triển các cơ hội xuất khẩu nông sản ngay lập tức. Thay vì hoạt động đơn độc, học viên có thể hợp tác trực tiếp với Trung Tâm Nông Nghiệp Việt Nam (VAC) và tiếp cận hệ sinh thái sản phẩm, chế biến & hỗ trợ xuất khẩu đã được thiết lập sẵn.",
