      "introDesc1": "在越南农业中心 (VAC)，我们深刻意识到长期农业成功依赖于生态责任。对于全球食品企业，ESG 合规已不仅是一项倡议，更是基本市场准入条件。",
      "introDesc2": "我们将可持续发展融入生态系统的每个层面。无论是管理大型契约农场还是咨询企业供应链，VAC 提供独立专业知识，协助保护环境并达到严苛的国际标准。",
      "certTitle": "提升供应链至高端标准",
      "certSub": "清洁标签与有机认证服务",
      "certText": "消费者对清洁、无化学残留及透明来源食品的需求是绝对的。将传统农业升级至国际标准需要严谨监管与独立验证。VAC 为寻求升级越南采购的企业提供专属认证咨询与管理。",
      "certBullet1": "有机转型管理：指导当地农场与加工工厂通过取得 USDA Organic 与 EU Organic 认证所需的多年度过渡规程。",
      "certBullet2": "GlobalG.A.P. 标准对接：实施良好的农业规范 (GAP)，重点关注工人福利、环境影响缓解与绝对食品安全。",
      "certBullet3": "清洁标签规程：设计并执行零农残耕作与加工规程，助力您的品牌在国际高监管市场推广清洁标签产品。",
      "certBullet4": "独立审计代表：我们的实地农艺师与合规专家作为您的独立代表参与官方环境与质量审计。",
      "circularTitle": "构建零废弃农业生态系统",
      "circularSub": "循环农业与资源优化",
      "circularText": "真正可持续的供应链物尽其用。VAC 与生产商和加工厂合作，推进“零废弃”循环倡议，使农业副产品留在经济循环中。",
      "circularBullet1": "生物质循环利用：设计并管理高营养农业副产品（如热带水果加工残渣）的回收利用，避免垃圾填埋。",
      "circularBullet2": "创造二次价值链：将这些回收材料转化为高消化率生物饲料与动物营养，在不额外消耗土地或水资源的前提下支持农业生态。",
