      "esgBullet1": "精准水资源管理：在密集的农业运营中强制实施水循环与过滤系统，消除有害径流并保护当地地下水。",
      "esgBullet2": "土地优化利用：通过技术驱动的高密度耕作方法最大化产量，同时最小化传统农业所需的土地占用。",
      "esgBullet3": "社会赋能：契约种植结构旨在为当地越南农户提供公平、标准化与丰厚的回报，为农村社区带来财务稳定与现代农业教育。",
