const LanguageContext = createContext<{
 language: Language;
 setLanguage: (lang: Language) => void;
 t: (key: string) => string;
}>({
 language: 'en',
 setLanguage: () => {},
 t: () => '',
});

export const LanguageProvider: React.FC<{ children: React.ReactNode }> = ({ children }) => {
 const [language, setLanguage] = useState<Language>('en');
 const [resources, setResources] = useState<TranslationResources>(defaultResources);

 useEffect(() => {
  let active = true;
  loadSiteResources().then((remoteResources) => {
   if (!active || !remoteResources) return;

   const mergedResources: TranslationResources = {
    en: { ...defaultResources.en },
    vi: { ...defaultResources.vi },
    zh: { ...defaultResources.zh },
    ko: { ...defaultResources.ko },
    ja: { ...defaultResources.ja }
   };

   for (const lang of ['en', 'vi', 'zh', 'ko', 'ja']) {
    if (remoteResources[lang]) {
     for (const section in remoteResources[lang]) {
      mergedResources[lang][section] = {
       ...(defaultResources[lang]?.[section] || {}),
       ...remoteResources[lang][section]
      };
     }
    }
   }

   startTransition(() => setResources(mergedResources));
  }).catch(() => {
   // Keep local fallback resources when Supabase is unavailable.
  });

  return () => {
   active = false;
  };
 }, []);

 const t = (path: string) => {
		const keys = path.split('.');
		let current: any = resources[language];
		
		for (const key of keys) {
			if (current[key] === undefined) {
				let fallback: any = resources['en'];
				for (const k of keys) {
					if (fallback[k] === undefined) return path;
					fallback = fallback[k];
				}
				current = fallback;
				break;
			}
			current = current[key];
		}
		
		if (typeof current === 'string') {
			current = current.replace(/simple netting structures?/gi, 'greenhouse structures');
			current = current.replace(/simple net structures?/gi, 'greenhouse structures');
			current = current.replace(/specialized netting structures?/gi, 'specialized greenhouse structures');
			current = current.replace(/cấu trúc lưới đơn giản/gi, 'cấu trúc nhà kính');
			current = current.replace(/cấu trúc lưới che chuyên dụng/gi, 'cấu trúc nhà kính chuyên dụng');
		}
		
		return current;
	};

 return (
  <LanguageContext.Provider value={{ language, setLanguage, t }}>
   {children}
  </LanguageContext.Provider>
 );
};

export const useTranslation = () => useContext(LanguageContext);
